'use strict';

/**
 * Golden test: MERN's GSTR-1 builder vs JSM's own GSTR-1 export, on JSM's real invoices.
 * Fixture: scripts/golden-master/extractJsmFixtures.js (read-only extract of JSM SQL + its GSTR-1 .xlsx).
 * The export in the fixture was generated by JSM for 01-Jun-2026 … 31-Jul-2026.
 */
const { describe, it, before } = require('node:test');
const assert = require('node:assert/strict');
const path = require('path');
const gstReturnService = require('../../services/gstReturnService');
const { toUqc } = require('../../utils/gstr1Lines');

const fixture = require(path.join(__dirname, 'fixtures', 'jsm_sc27.json'));
const jsm = fixture.jsmGstr1Export;
const COMPANY = { gstin: '24DZPPB8552M2ZS', stateCode: '24' };
const FROM = '2026-06-01';
const TO = '2026-07-31';

const r2 = (n) => Number(Number(n || 0).toFixed(2));

/** JSM FOLD_PER is the % taken off (5 = 5% less); MERN's line fold is the % kept (95). */
function mernFold(l) {
  if (l.foldPer) return r2(100 - l.foldPer);
  return l.amount && l.foldAmt ? r2(100 - (l.foldAmt / l.amount) * 100) : 0;
}

/** A JSM invoice in the shape MERN stores a Sales document. JSM's line fold-less amount is carried in dis1Amt. */
function toMernSale(s) {
  return {
    invoiceNo: s.invoiceNo,
    bookId: s.book,
    date: new Date(`${s.date}T00:00:00.000Z`),
    customerId: { name: s.partyName, gstin: s.partyGstin, stateCode: s.partyStateCode },
    taxableAmount: s.taxable,
    cgst: s.cgst,
    sgst: s.sgst,
    igst: s.igst,
    cess: s.cess,
    tcsAmount: s.tcs,
    roundOff: s.roundOff,
    netAmount: s.net,
    items: s.lines.map((l) => ({
      itemId: { name: l.itemName, hsnCode: l.hsnCode },
      unit: l.unit,
      pcs: l.pcs,
      mts: l.qty,
      rate: l.rate,
      amount: l.amount,
      fold: mernFold(l),
      dis1Amt: r2(l.foldAmt + l.dis1Amt + l.rdAmt),
      dis2Amt: l.dis2Amt,
      addAmt: l.addAmt,
      gstPer: l.gstPer,
    })),
  };
}

async function buildFromJsm() {
  const sales = fixture.sales
    .filter((s) => s.date >= FROM && s.date <= TO && !s.bookIsChallan && s.net !== 0)
    .map(toMernSale);
  const orig = {
    ctx: gstReturnService._companyCtx,
    sales: gstReturnService._salesInPeriod,
    cancelled: gstReturnService._cancelledSalesInPeriod,
    returns: gstReturnService._returnsInPeriod,
    notes: gstReturnService._notesInPeriod,
  };
  try {
    gstReturnService._companyCtx = async () => COMPANY;
    gstReturnService._salesInPeriod = async () => sales;
    gstReturnService._cancelledSalesInPeriod = async () => [];
    gstReturnService._returnsInPeriod = async () => [];
    gstReturnService._notesInPeriod = async () => [];
    return await gstReturnService.buildGstr1('jsm-golden', '072026', { startDate: FROM, endDate: TO });
  } finally {
    gstReturnService._companyCtx = orig.ctx;
    gstReturnService._salesInPeriod = orig.sales;
    gstReturnService._cancelledSalesInPeriod = orig.cancelled;
    gstReturnService._returnsInPeriod = orig.returns;
    gstReturnService._notesInPeriod = orig.notes;
  }
}

function assertSameRows(actual, expected, label) {
  const sort = (rows) => [...rows].sort((a, b) => a.key.localeCompare(b.key));
  const a = sort(actual);
  const e = sort(expected);
  assert.deepEqual(a.map((r) => r.key), e.map((r) => r.key), `${label}: row keys differ`);
  a.forEach((row, i) => assert.deepEqual(row, e[i], `${label}: row ${row.key} differs`));
}

describe('JSM golden: GSTR-1 (Sanchal Creation, Jun–Jul 2026) matches JSM export', () => {
  let g;
  before(async () => { g = (await buildFromJsm()).payload; });

  it('fixture carries JSM\'s export', () => {
    assert.ok(jsm, 'run extractJsmFixtures.js with --gstr1 to embed the JSM export');
  });

  it('B2B: same invoices, values, rates and taxable as JSM (one row per invoice per rate)', () => {
    const expected = jsm.b2b.map((r) => ({
      key: `${r['Invoice Number']}|${Number(r.Rate)}`,
      gstin: r['GSTIN/UIN of Recipient'],
      value: r2(r['Invoice Value']),
      pos: r['Place Of Supply'],
      taxable: r2(r['Taxable Value']),
    }));
    const actual = g.b2bRows.map((r) => ({
      key: `${r.invoiceNo}|${parseFloat(r.taxRate)}`,
      gstin: r.gstin,
      value: r2(r.netAmount),
      pos: r.stateName,
      taxable: r2(r.taxableAmount),
    }));
    assertSameRows(actual, expected, 'b2b');
  });

  it('B2CL: empty, as in JSM', () => {
    assert.equal(g.b2clRows.length, jsm.b2cl.length);
  });

  it('B2CS: same place-of-supply / rate buckets and taxable as JSM', () => {
    const expected = jsm.b2cs.map((r) => ({
      key: `${r['Place Of Supply']}|${Number(r.Rate)}`,
      type: r.Type,
      taxable: r2(r['Taxable Value']),
    }));
    const actual = g.b2cs.map((r) => ({
      key: `${r.pos_name}|${Number(r.rt)}`,
      type: r.typ,
      taxable: r2(r.txval),
    }));
    assertSameRows(actual, expected, 'b2cs');
  });

  for (const [label, field, sheet] of [['HSN (B2B)', 'hsnRows', 'hsnB2b'], ['HSN (B2C)', 'hsnB2cRows', 'hsnB2c']]) {
    it(`${label}: same HSN + UQC + rate rows, quantity, value, taxable and tax as JSM`, () => {
      const expected = jsm[sheet].map((r) => ({
        key: `${r.HSN}|${toUqc(r.UQC)}|${Number(r.Rate)}`,
        qty: r2(r['Total Quantity']),
        value: r2(r['Total Value']),
        taxable: r2(r['Taxable Value']),
        igst: r2(r['Integrated Tax Amount']),
        cgst: r2(r['Central Tax Amount']),
        sgst: r2(r['State/UT Tax Amount']),
      }));
      const actual = g[field].map((r) => ({
        key: `${r.hsn_sc}|${r.uqc}|${Number(r.rt)}`,
        qty: r2(r.qty),
        value: r2(r.val),
        taxable: r2(r.txval),
        igst: r2(r.iamt),
        cgst: r2(r.camt),
        sgst: r2(r.samt),
      }));
      assertSameRows(actual, expected, label);
    });
  }

  it('DOCS: one row per invoice series with JSM\'s from / to and net issued', () => {
    const expected = jsm.docs
      .filter((r) => r['Nature of Document'] === 'Invoices for outward supply')
      .map((r) => ({
        key: `${r['Sr. No. From']}-${r['Sr. No. To']}`,
        netIssued: Number(r['Total Number']) - Number(r.Cancelled),
      }));
    const actual = g.docsRows
      .filter((r) => r.docType === 'Invoices for outward supply')
      .map((r) => ({ key: `${r.from}-${r.to}`, netIssued: r.net_issue }));
    assertSameRows(actual, expected, 'docs');
  });

  it('B2B + B2CS + HSN all add up to the same taxable (internal consistency)', () => {
    const b2b = g.b2bRows.reduce((t, r) => t + r.taxableAmount, 0);
    const b2cs = g.b2cs.reduce((t, r) => t + r.txval, 0);
    const hsn = [...g.hsnRows, ...g.hsnB2cRows].reduce((t, r) => t + r.txval, 0);
    assert.equal(r2(b2b + b2cs), r2(hsn));
  });
});
